def compare_sequences(seq1: str, seq2: str):
    """
    Compare two protein/DNA sequences and return a list of differences.
    Each difference is a tuple: (position, seq1_residue, seq2_residue).
    Positions are 1-based.
    """
    diffs = []
    len1, len2 = len(seq1), len(seq2)
    min_len = min(len1, len2)

    # Compare positions within the shorter length
    for i in range(min_len):
        if seq1[i] != seq2[i]:
            diffs.append((i+1, seq1[i], seq2[i]))

    # Handle extra residues if sequences differ in length
    if len1 != len2:
        longer_seq = seq1 if len1 > len2 else seq2
        for i in range(min_len, max(len1, len2)):
            residue = longer_seq[i]
            if len1 > len2:
                diffs.append((i+1, residue, '-'))  # seq2 has no residue here
            else:
                diffs.append((i+1, '-', residue))  # seq1 has no residue here

    return diffs

if __name__ == "__main__":
    seq1 = ""
    
    seq2 = ""

    seq1 = seq1.strip()
    seq2 = seq2.strip()

    differences = compare_sequences(seq1, seq2)
    if not differences:
        print("The sequences are identical.")
    else:
        print(f"Found {len(differences)} difference(s):")
        for pos, r1, r2 in differences:
            print(f" Position {pos}: seq1='{r1}' vs seq2='{r2}'")